<?php use App\Core\View;?>
<div class="page-head"><div><h1>Webhooks</h1><p>Eventos recibidos y procesados fuera de la solicitud HTTP.</p></div></div>
<section class="panel table-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Recibido</th><th>Cuenta</th><th>Tópico</th><th>Recurso</th><th>Estado</th><th>Intentos</th><th>Error</th></tr></thead><tbody><?php if(!$events):?><tr><td colspan="7"><div class="empty">Aún no se han recibido eventos.</div></td></tr><?php endif;?><?php foreach($events as $e):?><tr><td><?= View::e($e['received_at']) ?></td><td><?= View::e($e['account_name']?:'Sin asociar') ?></td><td><?= View::e($e['topic']?:'—') ?></td><td><?= View::e($e['resource']?:'—') ?></td><td><span class="badge <?= $e['status']==='processed'?'green':($e['status']==='error'?'red':'amber') ?>"><?= View::e($e['status']) ?></span></td><td><?= (int)$e['attempts'] ?></td><td><?= View::e($e['error_message']?:'—') ?></td></tr><?php endforeach;?></tbody></table></div></section>
